(function(){var DESKTOP=window.matchMedia("(min-width: 1025px)");function init(){var form=document.querySelector('form.search-box[role="search"]');if(!form)return;var spacer=document.createElement("div");spacer.className="search-pin-spacer";spacer.setAttribute("aria-hidden","true");form.parentNode.insertBefore(spacer,form);var header=document.querySelector("header.site-header");var pinned=false;var queued=false;var GAP=8;function pinTop(){if(!header||getComputedStyle(header).position!=="sticky")return GAP;return Math.max(0,header.getBoundingClientRect().bottom)+GAP}function setPinned(on,top){if(on===pinned){if(on)form.style.top=top+"px";return}pinned=on;spacer.style.height=on?form.offsetHeight+"px":"";form.style.top=on?top+"px":"";form.classList.toggle("is-pinned",on)}function update(){queued=false;if(!DESKTOP.matches){setPinned(false);return}var top=pinTop();setPinned(spacer.getBoundingClientRect().top<top,top)}function queue(){if(queued)return;queued=true;requestAnimationFrame(update)}window.addEventListener("scroll",queue,{passive:true});window.addEventListener("resize",queue);if(DESKTOP.addEventListener)DESKTOP.addEventListener("change",queue);update()}if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",init);else init()})();